#!/usr/bin/env bash
# Writes the Homebrew formula and cask for a release into a tap checkout.
#
#   tap.sh VERSION checksums.txt TAPDIR
#
# VERSION is the release's version without the v. checksums.txt is the
# release's, listing the CLI archives and mdsh-gui's packages. TAPDIR is
# a checkout of the tap repository; Formula/mdsh.rb and Casks/mdsh.rb are
# written there. The workflow that calls this commits and pushes them.
set -euo pipefail

version=$1
sums=$2
tap=$3
repo=https://github.com/gdey/markdownshell
base=$repo/releases/download/v$version

# sum NAME prints the SHA-256 checksums.txt gives for the file NAME.
sum() {
  local s
  s=$(awk -v f="$2" '$2 == f { print $1 }' "$1")
  if [ -z "$s" ]; then
    echo "tap.sh: $1 has no entry for $2" >&2
    exit 1
  fi
  printf '%s' "$s"
}

# Look every checksum up first, so a missing file stops the script before
# anything is written (a failure inside the heredocs below would not).
dmg=mdsh-gui_${version}_macos_universal.dmg
sum_darwin_arm64=$(sum "$sums" "mdsh_${version}_darwin_arm64.tar.gz")
sum_darwin_amd64=$(sum "$sums" "mdsh_${version}_darwin_amd64.tar.gz")
sum_linux_arm64=$(sum "$sums" "mdsh_${version}_linux_arm64.tar.gz")
sum_linux_amd64=$(sum "$sums" "mdsh_${version}_linux_amd64.tar.gz")
sum_dmg=$(sum "$sums" "$dmg")

mkdir -p "$tap/Formula" "$tap/Casks"

cat > "$tap/Formula/mdsh.rb" <<RUBY
# Generated by .github/scripts/tap.sh in gdey/markdownshell for v$version.
class Mdsh < Formula
  desc "Run the code blocks in a markdown file, like a notebook that is plain markdown"
  homepage "$repo"
  version "$version"
  license "MIT"

  on_macos do
    on_arm do
      url "$base/mdsh_${version}_darwin_arm64.tar.gz"
      sha256 "$sum_darwin_arm64"
    end
    on_intel do
      url "$base/mdsh_${version}_darwin_amd64.tar.gz"
      sha256 "$sum_darwin_amd64"
    end
  end

  on_linux do
    on_arm do
      url "$base/mdsh_${version}_linux_arm64.tar.gz"
      sha256 "$sum_linux_arm64"
    end
    on_intel do
      url "$base/mdsh_${version}_linux_amd64.tar.gz"
      sha256 "$sum_linux_amd64"
    end
  end

  def install
    bin.install "mdsh"
    generate_completions_from_executable(bin/"mdsh", "completion", shells: [:bash, :zsh])
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/mdsh --version")
    (testpath/"hello.md").write <<~MARKDOWN
      # Hello

      \`\`\`sh {#hi}
      echo hello from brew
      \`\`\`
    MARKDOWN
    assert_match "hello from brew", shell_output("#{bin}/mdsh #{testpath}/hello.md")
  end
end
RUBY

cat > "$tap/Casks/mdsh.rb" <<RUBY
# Generated by .github/scripts/tap.sh in gdey/markdownshell for v$version.
cask "mdsh" do
  version "$version"
  sha256 "$sum_dmg"

  url "$base/mdsh-gui_#{version}_macos_universal.dmg"
  name "mdsh"
  desc "Desktop app that runs the code blocks in a markdown file"
  homepage "$repo"

  depends_on macos: ">= :ventura"

  app "mdsh.app"
  binary "#{appdir}/mdsh.app/Contents/MacOS/mdsh"

  # The app carries the mdsh command line tool, which the formula
  # installs to the same folder.
  conflicts_with formula: "mdsh"

  zap trash: [
    "~/Library/Application Support/mdsh",
    "~/Library/Saved Application State/com.gdey.mdsh.savedState",
  ]

  caveats <<~EOS
    mdsh.app is not signed with an Apple Developer ID. The first time it
    opens, macOS says it can't check it: choose Open Anyway in
    System Settings › Privacy & Security, or install with
      brew install --cask --no-quarantine mdsh
  EOS
end
RUBY

echo "wrote $tap/Formula/mdsh.rb and $tap/Casks/mdsh.rb for v$version"
